 static void Pump(int ms){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(15);}}
 static void Capture(Form form,string name){Pump(100);using var b=new Bitmap(form.Width,form.Height);using(var g=Graphics.FromImage(b))g.CopyFromScreen(form.Location,Point.Empty,b.Size);b.Save(Path.Combine(folder,name+".png"));}
 static async Task<string> Grant(AngraSyncTransport transport,string role,bool other=false){
 using var http=new HttpClient();string url=Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_URL")!+"&audience="+Uri.EscapeDataString("angra-sync-ci:"+transport.DeviceId);using var req=new HttpRequestMessage(HttpMethod.Get,url);req.Headers.Authorization=new("Bearer",Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_TOKEN"));var oidc=JsonNode.Parse(await (await http.SendAsync(req)).Content.ReadAsStringAsync())!;
 using var grantRequest=new HttpRequestMessage(HttpMethod.Post,AngraSyncTransport.Origin+"/sync/ci-grant");grantRequest.Headers.Authorization=new("Bearer",oidc["value"]!.ToString());grantRequest.Content=new StringContent(new JsonObject{["deviceId"]=transport.DeviceId,["role"]=role,["otherTenant"]=other^(Environment.GetEnvironmentVariable("ANGRA_QA_CHANNEL")=="003"),["publicKey"]=transport.PublicKey}.ToJsonString(),System.Text.Encoding.UTF8,"application/json");using var grant=await http.SendAsync(grantRequest);Check(grant.IsSuccessStatusCode,"GitHub OIDC grants isolated "+role+" test identity");return JsonNode.Parse(await grant.Content.ReadAsStringAsync())!["tenant"]!.ToString();
 }

 static async Task<(AngraSyncService Service,AngraSyncTransport App)> Setup(){using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var transport=new AngraSyncTransport(Convert.ToBase64String(key.ExportPkcs8PrivateKey()));var tenant=await Grant(transport,"pdv");var service=new AngraSyncService(transport,false);service.UseTestTenant(tenant);await service.Tick();using var appkey=ECDsa.Create(ECCurve.NamedCurves.nistP256);var app=new AngraSyncTransport(Convert.ToBase64String(appkey.ExportPkcs8PrivateKey()));await Grant(app,"app");return(service,app);}
 sealed class ReceiptFailure : DelegatingHandler{
  internal string Target="";internal int Blocked;
  internal ReceiptFailure():base(new HttpClientHandler{AllowAutoRedirect=false}){}
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){
   if(request.RequestUri!.AbsolutePath=="/sync/exchange"&&request.Content!=null){var body=JsonNode.Parse(await request.Content.ReadAsStringAsync(token))!;if((body["changes"] as JsonArray??new()).Any(x=>x?["id"]?.ToString()==Target&&!string.IsNullOrEmpty(x?["officialId"]?.ToString()))){Blocked++;return new HttpResponseMessage(System.Net.HttpStatusCode.ServiceUnavailable){Content=new StringContent("{\"error\":\"QA isolated receipt temporarily offline\"}")};}}
   return await base.SendAsync(request,token);
  }
 }
 static bool firstImport=true;
 static async Task<string> Import(AngraSyncService service,AngraSyncTransport app,string title){
  string id=Guid.NewGuid().ToString();var bob=service.Store!.Links().Single(l=>l.Entity=="clients"&&service.Store.ReadLocal(l)?["name"]?.ToString()=="CLIENTE FICTICIO QA");
  byte[] photo;using(var bitmap=new Bitmap(24,24)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.Cyan);using var stream=new MemoryStream();bitmap.Save(stream,System.Drawing.Imaging.ImageFormat.Jpeg);photo=stream.ToArray();}string sha=AngraSyncService.Hash(photo);
  var p=new JsonObject{["title"]=title,["type"]="Box de banheiro",["clientLocalId"]=bob.Id,["photoAttachment"]=new JsonObject{["sha256"]=sha,["sizeBytes"]=photo.Length,["mimeType"]="image/jpeg",["fileName"]="photo.jpg"},["measures"]=new JsonArray(new JsonObject{["label"]="Largura",["value"]="2",["unit"]="m",["mm"]="2000"},new JsonObject{["label"]="Altura",["value"]="2",["unit"]="m",["mm"]="2000"})};
  var r=await app.Call("/sync/exchange",new(){["changes"]=new JsonArray(new JsonObject{["entity"]="projects",["id"]=id,["baseRevision"]=0,["operationId"]=Guid.NewGuid().ToString(),["payload"]=p})});Check(r["results"]![0]!["ok"]!.GetValue<bool>(),"synthetic app project and JPEG manifest sent via actual signed HTTPS");
  await service.Tick();Check(service.Store.Link("projects",id).LocalId!=null,"actual SQLite project imported with Central closed");Check(!service.Notifications!.Unread().Any(n=>n.Id==id),"no alert before photo exists and is verified locally");
  var cap=await app.Call("/sync/photo-put",new(){["projectId"]=id,["sha256"]=sha,["size"]=photo.Length});await app.Binary(cap["url"]!.ToString(),photo);
  if(firstImport){firstImport=false;var field=typeof(AngraSyncTransport).GetField("http",I)!;var original=(HttpClient)field.GetValue(service.Transport)!;using var failure=new ReceiptFailure{Target=id};using var failing=new HttpClient(failure){Timeout=TimeSpan.FromSeconds(30)};field.SetValue(service.Transport,failing);try{await service.Tick();Check(failure.Blocked>0,"actual receipt request interrupted after real JPEG download and SQLite import");Check(service.Store.Link("projects",id).Pending!=null,"receipt remains pending for automatic retry");Check(service.Notifications!.Unread().Any(n=>n.Id==id),"alert survives receipt failure after real import with photo");Check(new AngraProjectNotifications(service.Store).Unread().Any(n=>n.Id==id),"unviewed alert with photo persists across journal restart before receipt ACK");}finally{field.SetValue(service.Transport,original);}}
  await service.Tick();Check(service.Status.Contains("PDV CONECTADO"),service.Status);Check(service.Notifications!.Unread().Count(n=>n.Id==id)==1,"receipt retry creates exactly one alert");Check(AngraSyncService.Hash(File.ReadAllBytes(AngraSyncService.PhotoPath(id,sha)))==sha,"actual HTTPS JPEG verified locally");return id;
 }
 static void AddProduct(Form sales){var search=All(sales).OfType<TextBox>().Single(x=>!x.ReadOnly&&x.Parent is not NumericUpDown);search.Text="QA-AVISO";using var confirm=new System.Windows.Forms.Timer{Interval=60};confirm.Tick+=(_,_)=>{var f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="Quantidade do Produto");if(f==null)return;confirm.Stop();f.DialogResult=DialogResult.OK;f.Close();};confirm.Start();typeof(Control).GetMethod("OnKeyDown",I)!.Invoke(search,new object[]{new KeyEventArgs(Keys.Enter)});}
 static string Cart(Form sales)=>string.Join("|",All(sales).OfType<DataGridView>().SelectMany(g=>g.Rows.Cast<DataGridViewRow>()).SelectMany(r=>r.Cells.Cast<DataGridViewCell>()).Select(c=>Convert.ToString(c.Value)));
 static bool Clickable(Form host,Control button){Point screen=button.PointToScreen(new Point(button.Width/2,button.Height/2));Control current=host;while(true){var child=current.GetChildAtPoint(current.PointToClient(screen));if(child==null)break;current=child;}return current==button||button.Contains(current);}
 static bool VisibleAlert(Form host){var a=All(host).OfType<AngraProjectAlert>().FirstOrDefault(c=>c.Visible);if(a==null)return false;var p=new Point(a.Left+20,a.Top+20);return host.GetChildAtPoint(p)==a;}
 [STAThread]static void Main(string[] args){baseline=args.Contains("before");Check(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true","isolated disposable Windows only");Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Directory.CreateDirectory(folder);Database.Initialize();Sql("INSERT OR REPLACE INTO settings(key,value) VALUES('company_registered','1'),('security_setup_completed','1'),('first_access_tutorial_completed','1'),('company_name','EMPRESA FICTICIA QA');INSERT INTO customers(name,document) VALUES('CLIENTE FICTICIO QA','QA-ISOLADO');INSERT INTO products(barcode,name,price,stock,active) VALUES('QA-AVISO','PRODUTO FICTICIO QA',12.50,10,1)");typeof(Auth).GetProperty("Current")!.SetValue(null,new UserSession(1,"OPERADOR QA","qa","ADMINISTRADOR","","",false));var setup=Setup().GetAwaiter().GetResult();using var service=setup.Service;using var app=setup.App;using var main=new MainForm();main.Text="LEAL INFO PDV PRO V"+UpdateManager.CurrentVersion+" — TESTE ISOLADO";using var alert=new AngraProjectAlert(main,service);Exception? failure=null;
 main.Shown+=async(_,_)=>{try{((System.Windows.Forms.Timer)typeof(MainForm).GetField("licenseTimer",I)!.GetValue(main)!).Stop();typeof(MainForm).GetField("automaticBackupCompleted",I)!.SetValue(main,true);await Task.Delay(5500);string id=await Import(service,app,"PROJETO QA PRINCIPAL");await Task.Delay(1500);var unread=service.Notifications!.Unread();bool visible=VisibleAlert(main);Console.WriteLine("DIAG main imported="+id+" unread="+unread.Count+" visible="+visible+" alert="+alert.Bounds+" z="+main.Controls.GetChildIndex(alert));Capture(main,"principal");results.Add(new{screen="main",unread=unread.Count,visible});if(!baseline)Check(visible&&unread.Any(n=>n.Id==id),"real main screen displays new imported project automatically");
 if(!baseline){service.Notifications!.MarkViewed(service.Store!.Link("projects",id).LocalId!);alert.RefreshNotice();Check(service.Notifications.Unread().Count==0,"sales starts with no unread alert and original available space");}Exception? saleFailure=null;using(var timer=new System.Windows.Forms.Timer{Interval=250}){bool started=false;timer.Tick+=async(_,_)=>{var sales=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f!=main&&f.Text.Contains("TELA DE VENDA"));if(sales==null||started)return;started=true;try{sales.Text+=" — TESTE ISOLADO V"+UpdateManager.CurrentVersion;AddProduct(sales);string cartBefore=Cart(sales);Check(cartBefore.Contains("PRODUTO FICTICIO QA"),"genuine sales cart contains synthetic product");var input=All(sales).OfType<TextBox>().First(t=>t.Visible&&t.Enabled&&!t.ReadOnly&&t.Parent is not NumericUpDown);input.Text="QA VENDA PRESERVADA";input.Focus();IntPtr foreground=GetForegroundWindow();string second=await Import(service,app,"PROJETO QA DURANTE VENDA");await Task.Delay(1500);bool shown=VisibleAlert(sales);Console.WriteLine("DIAG sales unread="+service.Notifications!.Unread().Count+" visible="+shown);Capture(sales,"vendas");results.Add(new{screen="sales",unread=service.Notifications.Unread().Count,visible=shown});if(!baseline){Check(shown,"real sales screen displays incoming project with Central closed");foreach(var b in All(sales).OfType<Button>().Where(b=>b.Text.Contains("Finalizar Venda")||b.Text.Contains("Cancelar Venda")))Check(Clickable(sales,b),"sales action remains visible and clickable: "+b.Text.Replace("\n"," "));Check(Cart(sales)==cartBefore&&input.Text=="QA VENDA PRESERVADA"&&input.Focused&&GetForegroundWindow()==foreground,"incoming alert preserves foreground, focus and sales input");Check(service.Notifications.Unread().Any(n=>n.Id==second),"sales notice is durable unread");int beforeOpen=service.Notifications.Unread().Count;Check(new AngraProjectNotifications(service.Store!).Unread().Count==beforeOpen,"positive unread count persisted before viewing");using var closer=new System.Windows.Forms.Timer{Interval=150};closer.Tick+=(_,_)=>{foreach(Form f in Application.OpenForms.Cast<Form>().Where(f=>f is AngraProjectForm).ToArray())f.Close();};closer.Start();All(sales).OfType<AngraProjectAlert>().Single().OpenFirst();closer.Stop();Check(service.Notifications.Unread().Count==beforeOpen-1,"explicit ABRIR PROJETO opens imported project and decrements only its unread count");Check(Cart(sales)==cartBefore,"explicit project viewing preserves existing sales cart");}sales.Close();}catch(Exception e){saleFailure=e;sales.Close();}};timer.Start();typeof(MainForm).GetMethod("OpenSales",I)!.Invoke(main,null);timer.Stop();}if(saleFailure!=null)throw saleFailure;
 if(!baseline){var count=service.Notifications!.Unread().Count;await service.Tick();await Task.Delay(1200);Check(service.Notifications.Unread().Count==count,"repeated sync never duplicates unread count");var reloaded=new AngraProjectNotifications(service.Store!);Check(reloaded.Unread().Count==count,"unread counter persists after reload");Check(!Application.OpenForms.Cast<Form>().Any(f=>f is GlassWorkshopForm),"Central never opened automatically");}
 }catch(Exception e){failure=e;}finally{File.WriteAllText(Path.Combine(folder,"results.json"),System.Text.Json.JsonSerializer.Serialize(new{baseline,results,error=failure?.ToString()}));main.Close();}};Application.Run(main);if(failure!=null)throw failure;Console.WriteLine("PASS REAL PDV ALERT SCENARIOS");}
